package com.fitbite.rag;
import com.fitbite.entity.Recipe; import com.fitbite.repository.RecipeRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class RecipeRetriever {private final RecipeRepository recipes;public RecipeRetriever(RecipeRepository recipes){this.recipes=recipes;} public List<Recipe> retrieve(String query){String q=query.toLowerCase();return recipes.findAll().stream().map(r->Map.entry(r,score(r,q))).filter(e->e.getValue()>0).sorted((a,b)->Double.compare(b.getValue(),a.getValue())).limit(5).map(Map.Entry::getKey).toList();}private double score(Recipe r,String q){double s=0;String text=(r.getName()+" "+r.getDescription()+" "+r.getDietaryTags()+" "+r.getHealthTags()+" "+r.getMealType()).toLowerCase();for(String t:q.split("\\W+"))if(t.length()>2&&text.contains(t))s++;for(var i:r.getIngredients())if(q.contains(i.getIngredient().getName().toLowerCase()))s+=2;return s;}}
